export function calcOrderCents(items = [], coupon = null) {
  let subtotal = 0;
  for (const item of items) {
    subtotal += item.priceCents * item.qty;
  }
  if (!coupon) return subtotal;
  if (coupon.type === 'fixed') {
    return Math.max(0, subtotal - coupon.value);
  }
  if (coupon.type === 'percent') {
    return subtotal * (1 - coupon.value / 100);
  }
  return subtotal;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {calcOrderCents} from '../src/order-total.mjs';

test('fixed coupon on active items', () => {
  const items = [{priceCents: 1000, qty: 2, status: 'active'}];
  assert.equal(calcOrderCents(items, {type: 'fixed', value: 500}), 1500);
});

export function paginateList(list = [], query = {}) {
  const page = query.page || 1;
  const limit = query.limit || 10;
  const offset = (page - 1) * limit;
  const items = list.slice(offset, offset + limit);
  return {
    page,
    limit,
    total: list.length,
    items,
  };
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {paginateList} from '../src/paginate.mjs';

test('numeric page and limit', () => {
  const res = paginateList([1, 2, 3, 4, 5], {page: 1, limit: 2});
  assert.deepEqual(res.items, [1, 2]);
});
